// Regenerates web/weights.js and web/styles.js from ../model.f16.bin and ../styles/*.npy.
// Usage: node web/tools/build-bundles.js
// The bundles are plain scripts because file:// pages cannot fetch() local files.
"use strict";
const fs = require("fs");
const path = require("path");

const WEB = path.join(__dirname, "..");
const ROOT = path.join(WEB, "..");

/** Minimal .npy reader: C-order arrays only. Returns {descr, shape, data: Buffer}. */
function readNpy(file) {
  const buf = fs.readFileSync(file);
  if (buf.toString("latin1", 0, 6) !== "\x93NUMPY") throw new Error(`${file}: not a .npy file`);
  const major = buf[6];
  const headerLen = major === 1 ? buf.readUInt16LE(8) : buf.readUInt32LE(8);
  const start = major === 1 ? 10 : 12;
  const header = buf.toString("latin1", start, start + headerLen);
  const descr = /'descr':\s*'([^']+)'/.exec(header)?.[1];
  const shapeSrc = /'shape':\s*\(([^)]*)\)/.exec(header)?.[1];
  if (!descr || shapeSrc === undefined || !/'fortran_order':\s*False/.test(header)) throw new Error(`${file}: unsupported header ${header}`);
  const shape = shapeSrc.split(",").map(s => s.trim()).filter(Boolean).map(Number);
  return { descr, shape, data: buf.subarray(start + headerLen) };
}

const blob = fs.readFileSync(path.join(ROOT, "model.f16.bin"));
if (blob.toString("latin1", 0, 4) !== "KGM1") throw new Error("model.f16.bin: bad magic");
fs.writeFileSync(path.join(WEB, "weights.js"),
  "// Generated by tools/build-bundles.js from model.f16.bin (KGM1 f16 weights). Do not edit.\n" +
  `globalThis.HW_WEIGHTS_B64 = "${blob.toString("base64")}";\n`);

const names = fs.readdirSync(path.join(ROOT, "styles"))
  .filter(f => f.endsWith("-strokes.npy")).map(f => f.slice(0, -"-strokes.npy".length))
  .sort((a, b) => (/^\d+$/.test(a) && /^\d+$/.test(b) ? a - b : a.localeCompare(b)));
const presets = names.map(name => {
  const s = readNpy(path.join(ROOT, "styles", `${name}-strokes.npy`));
  if (s.descr !== "<f4" || s.shape.length !== 2 || s.shape[1] !== 3 || s.data.length !== s.shape[0] * 12)
    throw new Error(`${name}-strokes.npy: expected little-endian float32 [T,3], got ${s.descr} ${s.shape}`);
  const c = readNpy(path.join(ROOT, "styles", `${name}-chars.npy`));
  if (!/^\|(u1|S\d+)$/.test(c.descr)) throw new Error(`${name}-chars.npy: expected uint8 or bytes, got ${c.descr}`);
  // model.py decodes with errors="ignore"; NUL padding of a fixed-width bytes scalar is dropped by cleanText anyway.
  return { name, chars: c.data.toString("utf8").replace(/\0+$/, ""), strokesB64: s.data.toString("base64") };
});
fs.writeFileSync(path.join(WEB, "styles.js"),
  "// Generated by tools/build-bundles.js from styles/*.npy. Do not edit.\n" +
  "// strokesB64: little-endian float32 [T,3] pen offsets (dx, dy, eos); chars: the text the strokes say.\n" +
  `globalThis.HW_PRESETS = ${JSON.stringify(presets, null, 1)};\n`);
console.log(`weights.js: ${blob.length} bytes of weights; styles.js: ${presets.length} presets (${names.join(", ")})`);
